import { Align } from "@kvisaz/phaser-sugar";
import { GameObject, onClick } from "../../../../common";

interface IProps {
  scene: Phaser.Scene;
  foreground: { textureName: string; frameName: string };
  // dont affect content!
  bodyScale?: number;
  shadow: { textureName: string; frameName: string };
  shadowOffsetY?: number;
  addContent?: (align: Align, bg: GameObject) => GameObject[];
  onClick: () => void;
  isMultipleClicks?: boolean; // По умолчанию кнопка одноразовая
  animationDuration?: number;
}

export class ButtonLayered extends Phaser.GameObjects.Container {
  private isClicking = false;
  private isDisabled = false;
  private readonly contentContainer: Phaser.GameObjects.Container;

  private get shadowOffsetY(): number {
    return this.props.shadowOffsetY ?? 12;
  }

  constructor(private props: IProps) {
    super(props.scene);
    const { scene, foreground, shadow, bodyScale = 1 } = props;

    const foregroundImage = new Phaser.GameObjects.Image(
      scene,
      0,
      0,
      foreground.textureName,
      foreground.frameName,
    ).setScale(bodyScale);
    const shadowImage = new Phaser.GameObjects.Image(scene, 0, 0, shadow.textureName, shadow.frameName).setScale(
      bodyScale,
    );
    const fgBounds = foregroundImage.getBounds();

    const boundsRect = new Phaser.GameObjects.Rectangle(
      scene,
      0,
      0,
      fgBounds.width,
      fgBounds.height + this.shadowOffsetY,
    );

    this.contentContainer = new Phaser.GameObjects.Container(scene);

    const align = new Align();
    align
      .anchor(boundsRect)
      .leftIn(shadowImage)
      .bottomIn(shadowImage)
      .leftIn(foregroundImage)
      .topIn(foregroundImage)
      .anchor(foregroundImage);

    onClick(boundsRect, this.onClick.bind(this));

    this.contentContainer.add([foregroundImage]);
    this.contentContainer.add(this.props.addContent?.(align, foregroundImage) ?? []);

    this.add([boundsRect, shadowImage, this.contentContainer]);
  }

  onClick() {
    if (this.isClicking || this.isDisabled) return;

    const {
      scene,
      onClick: onClickCallback,
      isMultipleClicks,
      animationDuration = 150,
      shadowOffsetY = 12,
    } = this.props;
    this.isClicking = true;
    const clickOffsetY = shadowOffsetY * 0.8;

    scene.tweens.add({
      targets: [this.contentContainer],
      y: () => clickOffsetY,
      duration: animationDuration,
      yoyo: true,
      ease: "Sine.easeInOut",
      onComplete: () => {
        this.isClicking = false;
        onClickCallback();
        if (!isMultipleClicks) {
          this.isDisabled = true;
        }
      },
    });
  }

  enable() {
    this.isDisabled = false;
  }

  disable() {
    this.isDisabled = true;
  }
}
