import { atlases } from "../atlases";
import { CardSuit, CardValue, getCardLetter, isNumberCard } from "../../common";
import { ASSETS } from "../Assets";
import { Align } from "@kvisaz/phaser-sugar";
import { layoutNumberCard } from "./layoutNumberCard";

const figureAtlas = atlases.figure;
const FIGURE_TEXTURE_NAME = figureAtlas.textureName;
type FigureFrameName = keyof (typeof figureAtlas)["frames"];

const cardAtlas = atlases.card;
const CARD_TEXTURE_NAME = cardAtlas.textureName;
type CardFrameName = keyof (typeof cardAtlas)["frames"];

const suitFrameNames: Record<CardSuit, CardFrameName> = {
  [CardSuit.diamond]: "suit.diamond.png",
  [CardSuit.heart]: "suit.heart.png",
  [CardSuit.spade]: "suit.spade.png",
  [CardSuit.club]: "suit.club.png",
};

const FIGURE_SCALE = 0.6; // для карт нужен небольшой размер

const suitCornerFrameNames: Record<CardSuit, CardFrameName> = {
  [CardSuit.diamond]: "suit.diamond.corner.png",
  [CardSuit.heart]: "suit.heart.corner.png",
  [CardSuit.spade]: "suit.spade.corner.png",
  [CardSuit.club]: "suit.club.corner.png",
};

interface IProps {
  scene: Phaser.Scene;
  locale: "en" | "ru";
  colorRed?: string;
  colorBlack?: string;
}

/**
 * билдер для обычных игровых кард на 52 карты
 * методы не должны меняться ни для одного пасьянса!
 * меняется только атласы - а в них нейминг один и тот жe
 * **/
export class CardAssetBuilder {
  private readonly scene: Phaser.Scene;
  private readonly locale: "en" | "ru";
  private readonly colorRed: string;
  private readonly colorBlack: string;

  constructor(props: IProps) {
    this.scene = props.scene;
    this.locale = props.locale;
    this.colorRed = props.colorRed ?? "#BC1E24";
    this.colorBlack = props.colorBlack ?? "#000000";
  }

  getSuitColor(suit: CardSuit): string {
    if (suit === CardSuit.diamond) return this.colorRed;
    if (suit === CardSuit.heart) return this.colorRed;
    return "#000000";
  }

  getFigureFrame(suit: CardSuit, value: CardValue): FigureFrameName | undefined {
    if (suit === CardSuit.club) {
      if (value === "jack") return "fig.club.j.png";
      if (value === "queen") return "fig.club.q.png";
      if (value === "king") return "fig.club.k.png";
    }

    if (suit === CardSuit.diamond) {
      if (value === "jack") return "fig.diamond.j.png";
      if (value === "queen") return "fig.diamond.q.png";
      if (value === "king") return "fig.diamond.k.png";
    }

    if (suit === CardSuit.heart) {
      if (value === "jack") return "fig.heart.j.png";
      if (value === "queen") return "fig.heart.q.png";
      if (value === "king") return "fig.heart.k.png";
    }

    if (suit === CardSuit.spade) {
      if (value === "jack") return "fig.spade.j.png";
      if (value === "queen") return "fig.spade.q.png";
      if (value === "king") return "fig.spade.k.png";
    }
  }

  figure(suit: CardSuit, value: CardValue): Phaser.GameObjects.Image | undefined {
    const frameName = this.getFigureFrame(suit, value);
    if (!frameName) return;
    return figImage(this.scene, frameName);
  }

  faceFrame() {
    const frameName: CardFrameName = "card.body.gray.mid.png";
    return cardImage(this.scene, frameName);
  }

  faceBg() {
    const frameName: CardFrameName = "card.body.bg.white.png";
    return cardImage(this.scene, frameName);
  }

  backCover() {
    const frameName: CardFrameName = "card.back.ornamental.png";
    return cardImage(this.scene, frameName);
  }

  back() {
    const cover = this.backCover();
    const bg = this.faceBg();
    const frame = this.faceFrame();
    new Align(frame).center(bg).center(cover);

    return new Phaser.GameObjects.Container(this.scene, 0, 0, [bg, cover, frame]);
  }

  suit(suit: CardSuit, isCorner = false) {
    return cardImage(this.scene, isCorner ? suitCornerFrameNames[suit] : suitFrameNames[suit]);
  }

  value(suit: CardSuit, value: CardValue) {
    const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
      fontSize: "38px",
      fontFamily: ASSETS.font.fonts.RobotoRegular.fontFamily,
      color: this.getSuitColor(suit),
      letterSpacing: -7,
    };

    const label = getCardLetter(value, this.locale);

    return new Phaser.GameObjects.Text(this.scene, 0, 0, label, textStyle);
  }

  cardFace(suit: CardSuit, value: CardValue) {
    const align = new Align();
    const bg = this.faceBg();
    const frame = this.faceFrame();

    const contentContainer = new Phaser.GameObjects.Container(this.scene);
    align.anchor(bg).center(frame);

    /** figure layout **/
    const figure = this.figure(suit, value);
    if (figure) {
      figure.setScale(FIGURE_SCALE);
      contentContainer.add(figure);
      align.anchor(frame).center(contentContainer);
    }

    /** number layout **/
    if (isNumberCard(value) || value === "ace") {
      const contentImages = layoutNumberCard({ value, align, builder: () => this.suit(suit) });
      contentContainer.add(contentImages);
    }
    align.anchor(frame).center(contentContainer);

    /** corner letter **/
    const valueLetter = this.value(suit, value);
    const offsetX = value === 10 ? 2 : 8;
    align.anchor(frame).leftIn(valueLetter, offsetX).topIn(valueLetter, 4);

    /** corner value **/
    const suitImage = this.suit(suit, true);
    align.anchor(valueLetter).centerX(suitImage).bottomTo(suitImage, 2);

    return new Phaser.GameObjects.Container(this.scene, 0, 0, [bg, contentContainer, valueLetter, suitImage, frame]);
  }
}

function cardImage(scene: Phaser.Scene, frameName: CardFrameName): Phaser.GameObjects.Image {
  return new Phaser.GameObjects.Image(scene, 0, 0, CARD_TEXTURE_NAME, frameName);
}

function figImage(scene: Phaser.Scene, frameName: FigureFrameName): Phaser.GameObjects.Image {
  return new Phaser.GameObjects.Image(scene, 0, 0, FIGURE_TEXTURE_NAME, frameName);
}
