import { ASSETS, BackgroundAssetBuilder } from "../../../assets";
import { services } from "../../../serviceProvider";
import { SoundManager } from "../../../ui";
import { globalEvents, GlobalSoundName } from "../../../globalEvents";
import { addBackButton, addTestButtons } from "../utils";
import { Scenes } from "../../routes";
import { resetSearchParam } from "../../../common";

export class SoundTestScene extends Phaser.Scene {
  preload() {}

  create() {
    console.log("SoundTestScene create");

    const scene = this;
    const { soundMusicSettings } = services;
    const soundManager = new SoundManager({ scene, soundMusicSettings });
    new BackgroundAssetBuilder(scene).sceneBg();

    const soundNames = Object.keys(ASSETS.sounds.effect);
    console.log(soundNames);

    /** backCover button **/
    addBackButton({
      scene: this,
      onClick: () => {
        resetSearchParam("test");
        scene.scene.start(Scenes.TestScene);
      },
    });

    /** Main Button **/
    addTestButtons({
      scene: this,
      title: "Sound Assets Tests",
      buttonsData: soundNames.map((soundName) => ({
        text: soundName,
        onClick: () => {
          globalEvents.emit("playSound", soundName as GlobalSoundName);
        },
      })),
    });
  }
}
