import { UiDialog } from "./UiDialog";
import { getLocalizedText, UiAssetBuilder } from "../assets";
import { Router } from "../scenes/routes";
import { UiSettingsDialog } from "./UiSettingsDialog";

/** показывать диалоги разного вида **/
export class Dialogs {
  private router: Router;
  private uiAssetBuilder: UiAssetBuilder;

  constructor(private scene: Phaser.Scene) {
    this.router = new Router(scene);
    this.uiAssetBuilder = new UiAssetBuilder(scene);
  }

  gameWin({ message, onOkClick }: { message: string; onOkClick: () => void }) {
    const { scene } = this;
    new UiDialog({
      scene,
      title: getLocalizedText("gameOver.win"),
      text: message,
      frameBuilder: (w, h) => this.uiAssetBuilder.dialogBg(w, h),
      contentFrameBuilder: (w, h) => this.uiAssetBuilder.dialogContentFrame(w, h),
      buttons: [
        {
          type: "accent",
          label: getLocalizedText("gameOver.nextGame").toUpperCase(),
          onClick: onOkClick,
        },
      ],
    });
  }

  gameFailed({ message, onOkClick }: { message: string; onOkClick: () => void }) {
    const { scene } = this;
    new UiDialog({
      scene,
      frameBuilder: (w, h) => this.uiAssetBuilder.dialogBg(w, h),
      contentFrameBuilder: (w, h) => this.uiAssetBuilder.dialogContentFrame(w, h),
      title: getLocalizedText("gameOver.gameOver"),
      titleTextStyle: {
        color: "#ff4603",
      },
      text: message,
      buttons: [
        {
          type: "accent",
          label: getLocalizedText("gameOver.tryAgain").toUpperCase(),
          onClick: onOkClick,
        },
      ],
    });
  }

  levelMapLevelBuy({
    money,
    onOkClick,
    onCancelClick,
  }: {
    money: number;
    onOkClick: () => void;
    onCancelClick: () => void;
  }) {
    const { scene } = this;
    new UiDialog({
      scene,
      frameBuilder: (w, h) => this.uiAssetBuilder.dialogBg(w, h),
      contentFrameBuilder: (w, h) => this.uiAssetBuilder.dialogContentFrame(w, h),
      title: getLocalizedText("levelMap.buy.Title"),
      text: getLocalizedText("levelMap.buy.Question", { money }),
      buttons: [
        {
          type: "accent",
          label: getLocalizedText("ok").toUpperCase(),
          onClick: onOkClick,
        },
        {
          type: "primary",
          label: getLocalizedText("cancel"),
          onClick: onCancelClick,
        },
      ],
    });
  }

  levelMapLevelLocked({ onOkClick }: { onOkClick: () => void }) {
    const { scene } = this;
    new UiDialog({
      scene,
      frameBuilder: (w, h) => this.uiAssetBuilder.dialogBg(w, h),
      contentFrameBuilder: (w, h) => this.uiAssetBuilder.dialogContentFrame(w, h),
      title: getLocalizedText("levelMap.buy.Locked.Title"),
      text: getLocalizedText("levelMap.buy.Locked.Info"),
      buttons: [
        {
          type: "accent",
          label: getLocalizedText("ok").toUpperCase(),
          onClick: onOkClick,
        },
      ],
    });
  }

  levelMapLevelNoMoney({ money, onOkClick }: { money: number; onOkClick: () => void }) {
    const { scene } = this;
    new UiDialog({
      scene,
      frameBuilder: (w, h) => this.uiAssetBuilder.dialogBg(w, h),
      contentFrameBuilder: (w, h) => this.uiAssetBuilder.dialogContentFrame(w, h),
      title: getLocalizedText("levelMap.buy.NotEnoughMoney.Title"),
      text: getLocalizedText("levelMap.buy.NotEnoughMoney.Info", { money }),
      iconOffset: {
        x: 20,
        y: 0,
      },
      buttons: [
        {
          type: "accent",
          label: getLocalizedText("ok").toUpperCase(),
          onClick: onOkClick,
        },
      ],
    });
  }

  backButton({
    title,
    text,
    onOkClick,
    onCancelClick,
  }: {
    title: string;
    text: string;
    onOkClick: () => void;
    onCancelClick: () => void;
  }) {
    const { scene } = this;
    new UiDialog({
      scene,
      frameBuilder: (w, h) => this.uiAssetBuilder.dialogBg(w, h),
      contentFrameBuilder: (w, h) => this.uiAssetBuilder.dialogContentFrame(w, h),
      title,
      text,
      buttons: [
        {
          type: "accent",
          label: getLocalizedText("ok").toUpperCase(),
          onClick: onOkClick,
        },
        {
          type: "primary",
          label: getLocalizedText("cancel").toUpperCase(),
          onClick: onCancelClick,
        },
      ],
    });
  }

  settings({ title, onOkClick }: { title: string; onOkClick: () => void }) {
    const { scene } = this;
    new UiSettingsDialog({
      scene,
      title,
      buttons: [
        {
          type: "accent",
          label: getLocalizedText("ok").toUpperCase(),
          onClick: onOkClick,
        },
      ],
    });
  }
}
