import { addNiceText } from "@kvisaz/phaser-sugar";
import { TextStyles } from "./styles";

export const text = {
  main: (scene: Phaser.Scene, text: string, wrapWidth?: number) =>
    addNiceText({ scene, text, style: { ...TextStyles.main, wrapWidth } }),
  mainLight: (scene: Phaser.Scene, text: string, wrapWidth?: number) =>
    addNiceText({ scene, text, style: { ...TextStyles.mainLight, wrapWidth } }),
};
