import { DialogLayer, IButton, UiCommonDialog } from "./UiCommonDialog";
import { ASSETS, getLocalizedText, UiAssetBuilder } from "../assets";
import { Align } from "@kvisaz/phaser-sugar";
import { uiIconSoundButton, UiMusicButton } from "./buttons";
import { services } from "../serviceProvider";
import { SceneEvents } from "../SceneEvents";

interface IProps {
  scene: Phaser.Scene;
  title: string;
  overlayAlpha?: number;
  buttons: IButton[];
}

const WIDTH = 520;
const HEIGHT = 400;
const contentWidth = WIDTH - 42;
const contentHeight = HEIGHT - 132;

export class UiSettingsDialog extends UiCommonDialog {
  constructor(props: IProps) {
    super({
      ...props,
      bgBuilder(): DialogLayer {
        return new UiAssetBuilder(props.scene).dialogBg(WIDTH, HEIGHT);
      },
      contentFrameBuilder(): DialogLayer {
        return new UiAssetBuilder(props.scene).dialogContentFrame(contentWidth, contentHeight);
      },
      contentBuilder(contentFrame: DialogLayer): DialogLayer {
        const { scene } = props;
        const align = new Align();
        const container = new Phaser.GameObjects.Container(scene);

        const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
          fontFamily: ASSETS.font.fonts.RobotoBold.fontFamily,
          color: "#23394C",
          fontSize: "24px",
        };

        const soundMusicSettings = services.soundMusicSettings;
        const sceneEvents = new SceneEvents(scene);
        const unSubs: (() => void)[] = [];
        container.on(Phaser.GameObjects.Events.DESTROY, () => {
          unSubs.forEach((unSub) => unSub());
          unSubs.length = 0;
        });

        /** sound on/off **/
        const soundButton = uiIconSoundButton({ scene });
        const soundLabel = getLocalizedText(
          soundMusicSettings.isSoundOn() ? "settings.sound.on" : "settings.sound.off",
        );
        const soundText = new Phaser.GameObjects.Text(scene, 0, 0, soundLabel, textStyle);
        align.anchor(soundButton).rightTo(soundText, 16).centerY(soundText);

        const checkSoundState = (isSoundOn: boolean) => {
          soundText.setText(getLocalizedText(isSoundOn ? "settings.sound.on" : "settings.sound.off"));
          soundText.setAlpha(isSoundOn ? 1 : 0.5);
        };
        checkSoundState(soundMusicSettings.isSoundOn());

        unSubs.push(
          sceneEvents.on("soundSettingsOn", (isSoundOn) => {
            checkSoundState(isSoundOn);
          }),
        );

        /** music on/off **/
        const musicButton = new UiMusicButton({ scene });
        align.anchor(soundButton).bottomTo(musicButton, 32).leftIn(musicButton);

        const musicLabel = getLocalizedText(
          soundMusicSettings.isMusicOn() ? "settings.music.on" : "settings.music.off",
        );
        const musicText = new Phaser.GameObjects.Text(scene, 0, 0, musicLabel, textStyle);
        align.anchor(musicButton).rightTo(musicText, 16).centerY(musicText);

        const checkMusicState = (isMusicOn: boolean) => {
          musicText.setText(getLocalizedText(isMusicOn ? "settings.music.on" : "settings.music.off"));
          musicText.setAlpha(isMusicOn ? 1 : 0.5);
        };

        checkMusicState(soundMusicSettings.isMusicOn());

        unSubs.push(
          sceneEvents.on("musicSettingsOn", (isMusicOn) => {
            checkMusicState(isMusicOn);
          }),
        );

        /** language ??? **/

        container.add([soundButton, soundText, musicButton, musicText]);
        return container;
      },
    });
  }
}
