import { DragObject, DropZone } from "../dragdrop";
import { overlapAreaByBounds } from "../dragdrop/DragDropZen/overlap/overlap";
import { IBoundable } from "../games/cards-abstract/abstract_types";

export type DragDropChecker<Zone extends IBoundable = IBoundable> = (drag: DragObject, drop: Zone) => boolean;

export interface OverlapAreaConfig {
  isDroppable: DragDropChecker;
  getOverlapArea?: (drag: DragObject, drop: DropZone) => number;
  dropZoneSelection?: "first" | "maxOverlap";
  minOverlapArea?: number;
}

export function findFirstOverlap(
  gameObject: DragObject,
  zones: DropZone[],
  config: OverlapAreaConfig,
): DropZone | null {
  const overlapArea = config.getOverlapArea ?? overlapAreaByBounds;
  for (let i = 0; i < zones.length; i++) {
    const dz = zones[i];
    if (!config.isDroppable(gameObject, dz)) continue;
    if (overlapArea(gameObject, dz) > 0) {
      return dz;
    }
  }
  return null;
}

export function findMaxOverlap(gameObject: DragObject, zones: DropZone[], config: OverlapAreaConfig): DropZone | null {
  let best: DropZone | null = null;
  let bestArea = config.minOverlapArea ?? 0;

  const overlapArea = config.getOverlapArea ?? overlapAreaByBounds;

  for (let i = 0; i < zones.length; i++) {
    const dz = zones[i];
    if (!config.isDroppable(gameObject, dz)) continue;

    const area = overlapArea(gameObject, dz);
    if (area >= bestArea) {
      bestArea = area;
      best = dz;
    }
  }
  return best;
}

/** вернуть дропзону которая позволяет **/
export function findSimpleMaxOverlap<Zone extends IBoundable>(
  gameObject: DragObject,
  zones: Zone[],
  isDroppable: DragDropChecker<Zone>,
  minOverlapArea = 0,
): Zone | null {
  let best: Zone | null = null;
  let bestArea = minOverlapArea;

  const overlapArea = overlapAreaByBounds;

  for (let i = 0; i < zones.length; i++) {
    const dz = zones[i];
    if (!isDroppable(gameObject, dz)) continue;

    const area = overlapArea(gameObject, dz);
    if (area <= 0) continue;
    if (area > bestArea) {
      bestArea = area;
      best = dz;
    }
  }
  return best;
}

export function findFirstDroppableOverlap(
  gameObject: DragObject,
  zones: DropZone[],
  config: OverlapAreaConfig,
): DropZone | null {
  return config.dropZoneSelection === "first"
    ? findFirstOverlap(gameObject, zones, config)
    : findMaxOverlap(gameObject, zones, config);
}
