import { Align, cssColorToInt } from "@kvisaz/phaser-sugar";
import { buttonSimple, IButton } from "../../Button";
import { GameObject, getCanvasSize } from "../../../../common";
import { background01, Background01Styles } from "../../Background";
import { Ui } from "../../index";

interface IProps {
  scene: Phaser.Scene;
  message: string;
  buttons: IButton[];
  width?: number;
  height?: number;
  padding?: number;
  isNotAutoClosing?: boolean;
}

/**
 * Максимально реюзабельно и универсально
 */
export class BasicDialog extends Phaser.GameObjects.Container {
  public shadow: Phaser.GameObjects.Rectangle | undefined;

  constructor({ scene, padding = 15, ...props }: IProps) {
    super(scene);
    const canvasSize = getCanvasSize(scene);
    const width = props.width ?? Math.round(canvasSize.width / 2);
    const height = props.height ?? Math.round(canvasSize.height / 2);

    const bgColor = cssColorToInt("#3b3838");
    const bgBorderSize = 2;
    const bgBorderColor = cssColorToInt("#4b4949");
    const bg = new Phaser.GameObjects.Rectangle(scene, 0, 0, width, height, bgColor);
    bg.setStrokeStyle(bgBorderSize, bgBorderColor);

    const buttonHeight = 50;
    const buttonsAmount = 2;
    const buttonWidth = Math.round((width - padding * (buttonsAmount + 1)) / buttonsAmount);

    const desc = createDescription({
      scene,
      text: props.message,
      width: width - padding * 2,
      height: height - padding * 3 - buttonHeight,
    });

    const buttonContainer = new Phaser.GameObjects.Container(scene);
    const buttons = props.buttons.map((buttonData) =>
      buttonSimple({
        scene,
        label: buttonData.label,
        onClick: () => {
          buttonData.onClick();
          if (props.isNotAutoClosing) return;

          this.destroy();
        },
        width: buttonWidth,
        height: buttonHeight,
      }),
    );

    const align = new Align();
    let currentAnchor = buttons[0];
    buttons.forEach((next, i) => {
      if (i === 0) return;
      align.anchor(currentAnchor).rightTo(next, padding).centerY(next);
      currentAnchor = next;
    });
    buttonContainer.add(buttons);

    align.anchor(bg).centerX(desc).topIn(desc, padding).centerX(buttonContainer).bottomIn(buttonContainer, -padding);
    this.add([bg, desc, buttonContainer]);

    /** add shadow **/
    const sceneBounds = getCanvasSize(scene);
    this.shadow = new Phaser.GameObjects.Rectangle(scene, 0, 0, sceneBounds.width, sceneBounds.height, 0x000000, 0.2);
    this.shadow.setInteractive();
    scene.add.existing(this.shadow);
    align.anchorSceneScreen(scene).center(this.shadow);

    /** place in center **/
    scene.add.existing(this);
    align.anchorSceneScreen(scene).center(this);
  }

  destroy(fromScene?: boolean) {
    super.destroy(fromScene);
    this.shadow?.destroy();
  }
}

interface IDescriptionProps {
  scene: Phaser.Scene;
  text: string;
  width: number;
  height: number;
}

function createDescription({ scene, text, width, height }: IDescriptionProps): GameObject {
  const bg = background01({
    scene,
    width,
    height,
    style: Background01Styles.grayLight,
  });

  const wrapWidth = width - 30;
  const textObj = Ui.text.mainLight(scene, text, wrapWidth);

  new Align(bg).center(textObj);

  return new Phaser.GameObjects.Container(scene, 0, 0, [bg, textObj]);
}
