/** Глобальные эвенты в формате key->dataType э**/
export interface ISceneEvents {
  /** реакия на кнопки настроке **/
  soundSettingsOn: boolean;
  musicSettingsOn: boolean;
  /** команда на запуск музыки **/
  musicPlay: undefined;
  /** команда на звуковой эффект **/
  soundEffect: SoundEffect;
  /** сохрани золото **/
  savePlayerGold: number;
  /** передаем в метагейм через sceneEvents **/
  saveLevelPlay: { levelId: number; isPlayerWin: boolean };
  unlockLevel: { levelId: number };
}

export enum SoundEffect {
  click = "click",
  coinFlip = "coinFlip",
  explode = "explode",
  gameWinMusic = "gameWinMusic",
  buttonHover = "buttonHover",
}

/** Обертка для эвентов под сцену **/
export class SceneEvents {
  constructor(private scene: Phaser.Scene) {}

  emit<T extends keyof ISceneEvents>(eventName: T, data: ISceneEvents[T]) {
    this.scene.events.emit(eventName, data);
  }

  on<T extends keyof ISceneEvents>(eventName: T, callback: (data: ISceneEvents[T]) => void) {
    this.scene.events.on(eventName, callback);

    return () => this.off(eventName, callback);
  }

  off<T extends keyof ISceneEvents>(eventName: T, callback?: (data: ISceneEvents[T]) => void) {
    this.scene.events.off(eventName, callback);
  }

  once<T extends keyof ISceneEvents>(eventName: T, callback: (data: ISceneEvents[T]) => void) {
    this.scene.events.once(eventName, callback);
  }
}
