import * as en from "./json/en.json";
import * as ru from "./json/ru.json";
import { renderTemplateString } from "../../common";

const texts = {
  en,
  ru,
} as const;

export type Locale = keyof typeof texts;
export type LocaleKey = keyof typeof texts.en;

/** simple dimple localization **/

let locale: Locale = "ru";

const setLocale = (newLocale: Locale) => (locale = newLocale);

export const getCurrentLocale = () => locale;

export const setLocaleFromString = (localeStr: string) => {
  localeStr = localeStr.trim();

  if (localeStr === "ru") {
    setLocale("ru");
    return;
  }

  /** default **/
  setLocale("en");
};

export const getLocalizedText = (text: LocaleKey, data: Record<string, string | number> = {}): string => {
  return renderTemplateString(texts[locale][text], data);
};
