import {Align, AlignObject} from "@kvisaz/phaser-sugar";
import {
    ArrangeOrder,
    arrangeOrder,
    cardClassic52Deck,
    CardSuit,
    CardValue,
    DragObject,
    findSimpleMaxOverlap,
    GameObjectBuilder,
    makeArray,
    setContainerInteractive,
} from "../../../common";
import {CardAssetBuilder} from "../../../assets";
import {CardSide, IBoundable} from "../../../common/games/cards-abstract/abstract_types";
import {KlondikeSolitaireRules} from "./KlondikeSolitaireRules";
import {KlondikeStack} from "./KlondikeStack";
import {IKlondikeCard, IKlondikeStack, KlondikeStackType} from "./interfaces";
import {ifKlondikeCard, isKlondikeCard, KlondikeCard} from "./KlondikeCard";
import {animateCardFlip, animateCardMove, animateCardShake, layoutForAnimation} from "./cardAnimations";
import {KlondikeEventsEmitter, SolitaireAction} from './KlondikeEvents';

interface IProps {
    scene: Phaser.Scene;
    locale: "en" | "ru";
    fieldBounds: { getBounds: () => Phaser.Geom.Rectangle };
    // Размер дроп зоны должен учитывать  размер стопки!
    // для начала сделаем за счет размера самой дроп зоны - фиксированного
    builders: {
        // колода
        deckZone: GameObjectBuilder;
        // кладбище
        graveZone: GameObjectBuilder;
        // базы для складывания
        baseBuilder: GameObjectBuilder;
        // рабочие стопки
        pileBuilder: GameObjectBuilder;
    };
    cardLayout: {
        deck: (items: AlignObject[], inputZone: IBoundable) => void;
        grave: (items: AlignObject[], inputZone: IBoundable) => void;
        base: (items: AlignObject[], inputZone: IBoundable) => void;
        pile: (items: AlignObject[], inputZone: IBoundable) => void;
    };
}

interface DragState {
    draggedCard: IKlondikeCard;
    cards: IKlondikeCard[];
    offsets: Map<IKlondikeCard, { x: number; y: number }>;
    startPositions: Map<IKlondikeCard, { x: number; y: number }>;
    fromStack: IKlondikeStack;
}

export class KlondikeView {
    private readonly align = new Align();
    private readonly klondikeRules = new KlondikeSolitaireRules();
    public events = new KlondikeEventsEmitter();

    private readonly cardStacksMap: {
        deck: IKlondikeStack;
        grave: IKlondikeStack;
        bases: IKlondikeStack[];
        piles: IKlondikeStack[];
    };
    private readonly cardStacks: IKlondikeStack[];
    private readonly cardViews: IKlondikeCard[];
    private dragState: DragState | null = null;

    private state = {
        isCardMoveAnimation: true,
    };

    constructor(private props: IProps) {
        const {cardLayout} = this.props;

        const cardPlaces = this.createCardPlaces();

        /** Стопки карт
         * автоматически обрабатывают выравнивание по зонам
         * и коллекции
         * **/
        this.cardStacksMap = {
            deck: new KlondikeStack({
                id: KlondikeStackType.DECK,
                type: KlondikeStackType.DECK,
                cardPlace: cardPlaces.deck,
                layoutStrategy: cardLayout.deck,
            }),
            grave: new KlondikeStack({
                id: KlondikeStackType.GRAVE,
                type: KlondikeStackType.GRAVE,
                cardPlace: cardPlaces.grave,
                layoutStrategy: cardLayout.grave,
            }),
            bases: cardPlaces.bases.map((basePlace, index) => {
                return new KlondikeStack({
                    id: `${KlondikeStackType.BASE}-${index}`,
                    type: KlondikeStackType.BASE,
                    cardPlace: basePlace,
                    layoutStrategy: cardLayout.base,
                });
            }),
            piles: cardPlaces.piles.map((pilePlace, index) => {
                return new KlondikeStack({
                    id: `${KlondikeStackType.PILE}-${index}`,
                    type: KlondikeStackType.PILE,
                    cardPlace: pilePlace,
                    layoutStrategy: cardLayout.pile,
                });
            }),
        };
        this.cardStacks = [
            this.cardStacksMap.deck,
            this.cardStacksMap.grave,
            ...this.cardStacksMap.bases,
            ...this.cardStacksMap.piles,
        ];

        this.cardViews = this.createCards(this.cardStacksMap.deck);
        this.dealInitialTableau();
        this.addUserInput();
    }

    private createCardPlaces() {
        const {align, props, klondikeRules} = this;
        const {scene, builders, fieldBounds} = props;

        const deck = builders.deckZone();
        const grave = builders.graveZone();

        const bases = makeArray(klondikeRules.BASE_AMOUNT).map(() => builders.baseBuilder());
        const piles = makeArray(klondikeRules.PILES_AMOUNT).map(() => builders.pileBuilder());

        const padding = 16;
        align.anchor(fieldBounds).leftIn(deck).topIn(deck);
        align.anchor(deck).rightTo(grave, padding).centerY(grave);

        const baseBounds = bases[0].getBounds();
        bases.forEach((base, i) => {
            align
                .anchor(fieldBounds)
                .rightIn(base, -(baseBounds.width + padding) * i)
                .topIn(base);
        });

        const pileBounds = piles[0].getBounds();
        piles.forEach((pile, i) => {
            align
                .anchor(bases[0])
                .rightIn(pile, -(pileBounds.width + padding) * i)
                .bottomTo(pile, padding * 2);
        });

        return {
            deck,
            grave,
            bases,
            piles,
        };
    }

    private createCards(initStack: IKlondikeStack) {
        const {align, props} = this;
        const {scene, builders, locale} = props;

        /** select data for cardCollections **/
        const playCards = Phaser.Utils.Array.Shuffle([...cardClassic52Deck.cards.all]);
        console.log("playCards", playCards);

        /** card builder **/
        const cardAssetBuilder = new CardAssetBuilder({scene, locale});
        const cardBuilder = (suit: CardSuit, value: CardValue) =>
            new KlondikeCard({
                scene,
                suit,
                value,
                initStack,
                scale: 0.55,
                initSide: "back",
                faceImage: cardAssetBuilder.cardFace(suit, value),
                backImage: cardAssetBuilder.back(),
            });

        /** cardViews **/
        const cardViews = playCards.map((playCard) => cardBuilder(playCard.suit, playCard.value));

        return cardViews;
    }

    /**
     * Раскладывает стартовые карты по рабочим стопкам согласно правилам пасьянса «Косынка».
     */
    private dealInitialTableau(order: "increasing" | "decreasing" = "increasing") {
        const {cardStacksMap, cardViews} = this;

        cardStacksMap.deck.placeCards(cardViews);

        const piles = [...cardStacksMap.piles];
        if (order === "increasing") piles.reverse();

        const pilesAmount = piles.length;
        for (let row = 0; row < pilesAmount; row++) {
            for (let pileIndex = row; pileIndex < pilesAmount; pileIndex++) {
                const card = cardStacksMap.deck.pickTopCard();
                if (!card) {
                    return;
                }
                const pile = piles[pileIndex];
                const isFaceUp = pileIndex === row ? true : false;
                // pile.placeCardOnTop(card, cardSide);
                pile.placeCards([card]);
                if (isFaceUp) {
                    card.flip("face");
                }
            }
        }
    }

    private addUserInput() {
        this.cardViews.forEach((cardView) => {
            cardView.setInteractive({useHandCursor: true});
        });

        this.props.scene.input.setDraggable(this.cardViews);
        this.props.scene.input.on(Phaser.Input.Events.GAMEOBJECT_POINTER_UP, this.onPointerUp.bind(this));
        this.props.scene.input.on(Phaser.Input.Events.GAMEOBJECT_POINTER_OVER, this.onPointerOver.bind(this));
        this.addInputDragging();
    }

    /** Одноразовый клик по колоде - как правило для ее обновления из кладбища
     *  применять когда колода опустела
     * **/
    private addOnceDeckClick(onClick: () => void) {
        const {cardPlace} = this.cardStacksMap.deck;
        if (cardPlace.type === "Container") {
            setContainerInteractive(cardPlace as Phaser.GameObjects.Container);
        }
        cardPlace.setInteractive({useHandCursor: true});
        cardPlace.once(Phaser.Input.Events.GAMEOBJECT_POINTER_UP, onClick);
    }

    private checkIfDeckIsVoid() {
        if (this.cardStacksMap.deck.length > 0) return;

        /** колода пустая - добавляем к ее зоне одноразовый клик для перезапуска **/
        this.addOnceDeckClick(() => {
            const {deck, grave} = this.cardStacksMap;
            grave.moveAsToDeck(deck);
            this.events.emit("solitaireAction", SolitaireAction.STOCK_RECYCLE);
        });
    }

    private onCardMoveFinish(card: IKlondikeCard, from: IKlondikeStack, to: IKlondikeStack) {
        console.log("onCardMoveFinish", from.type, to.type);

        this.emitMoveEvent(from, to);

        if (from.type === "deck") {
            this.checkIfDeckIsVoid();
        }

        this.checkGameWon();
    }

    private emitMoveEvent(from: IKlondikeStack, to: IKlondikeStack) {
        if (to.type === KlondikeStackType.BASE) {
            this.events.emit("solitaireAction", SolitaireAction.MOVE_TO_FOUNDATION);
            return;
        }

        if (to.type === KlondikeStackType.PILE) {
            if (from.type === KlondikeStackType.DECK || from.type === KlondikeStackType.GRAVE) {
                this.events.emit("solitaireAction", SolitaireAction.MOVE_STOCK_TO_TABLEAU);
            } else if (from.type === KlondikeStackType.PILE) {
                this.events.emit("solitaireAction", SolitaireAction.MOVE_TABLEAU_TO_TABLEAU);
            }
        }
    }

    private checkGameWon() {
        const allBasesComplete = this.cardStacksMap.bases.every(base => base.length === 13);
        if (allBasesComplete) {
            this.events.emit("solitaireAction", SolitaireAction.GAME_WON);
        }
    }

    private onPointerOver(pointer: Phaser.Input.Pointer, objects: Phaser.GameObjects.GameObject[]) {
        const obj = objects[0];
        if (obj == null) return;

        console.log("GAMEOBJECT_POINTER_OVER on type ", obj.type);

        if (isKlondikeCard(obj)) {
            const card = obj;
            console.log(`GAMEOBJECT_POINTER_OVER
        value ${card.value} 
        suit ${card.suit} 
        side ${card.isFaceUp ? "face" : "back"}
        stack ${card.stack?.type} ${card.stack?.id}  
      `);
        }
    }

    private addInputDragging() {
        const isDroppable = (gameObject: Phaser.GameObjects.GameObject, dropZone: IKlondikeStack): boolean => {
            const card = ifKlondikeCard(gameObject);
            return this.klondikeRules.isDroppable(card, dropZone);
        };

        this.props.scene.input.on(
            Phaser.Input.Events.DRAG_START,
            (pointer: Phaser.Input.Pointer, gameObject: Phaser.GameObjects.GameObject) => {
                const card = ifKlondikeCard(gameObject);
                if (card == null) return;

                const fromStack = card.stack;

                this.dragState = null;
                if (!this.klondikeRules.isCardMovable(card)) {
                    return;
                }

                const movableCards = this.klondikeRules.getPileMovableCards(card);
                const cards = movableCards.length > 0 ? movableCards : [card];

                const offsets = new Map<IKlondikeCard, { x: number; y: number }>();
                const startPositions = new Map<IKlondikeCard, { x: number; y: number }>();

                cards.forEach((movableCard) => {
                    offsets.set(movableCard, {x: movableCard.x - card.x, y: movableCard.y - card.y});
                    startPositions.set(movableCard, {x: movableCard.x, y: movableCard.y});
                    arrangeOrder(movableCard, ArrangeOrder.top);
                });

                this.dragState = {
                    draggedCard: card,
                    cards,
                    offsets,
                    startPositions,
                    fromStack,
                };
            },
        );

        this.props.scene.input.on(
            Phaser.Input.Events.DRAG,
            (
                pointer: Phaser.Input.Pointer,
                object: Phaser.GameObjects.GameObject & AlignObject,
                dragX: number,
                dragY: number,
            ) => {
                if (!this.dragState) return;
                const {cards, offsets, draggedCard} = this.dragState;

                cards.forEach((draggedCard) => {
                    const offset = offsets.get(draggedCard);
                    if (!offset) return;
                    draggedCard.x = dragX + offset.x;
                    draggedCard.y = dragY + offset.y;
                });

                const dropZone = findSimpleMaxOverlap<IKlondikeStack>(draggedCard, this.cardStacks, isDroppable);
                if (dropZone) {
                    console.log("dropZone", dropZone);
                }
            },
        );

        this.props.scene.input.on(
            Phaser.Input.Events.DRAG_END,
            (pointer: Phaser.Input.Pointer, gameObject: DragObject, dropped: boolean) => {
                if (!this.dragState) return;

                const dropZone = findSimpleMaxOverlap<IKlondikeStack>(this.dragState.draggedCard, this.cardStacks, isDroppable);

                if (dropZone === null) {
                    this.restoreDraggedCards(this.dragState);
                    return;
                }

                const movingCards = this.dragState.cards;
                const fromStack = this.dragState.fromStack;

                movingCards.forEach((movingCard) => {
                    fromStack.removeCard(movingCard);
                });

                dropZone.placeCards(movingCards);

                if (fromStack.topCard && !fromStack.topCard.isFaceUp) {
                    animateCardFlip({card: fromStack.topCard}).catch(console.warn);
                }

                this.onCardMoveFinish(this.dragState.draggedCard, fromStack, dropZone);

                this.dragState = null;
            },
        );
    }

    private async tryAutoMove(card: IKlondikeCard): Promise<boolean> {
        const fromStack = card.stack;
        // карту нельзя двигать вообще
        if (!this.klondikeRules.isCardMovable(card)) {
            return false;
        }

        // ищем для нее подходящую стопку
        const targetStack = this.findAutoMoveTarget(card);
        if (!targetStack) {
            return false;
        }

        // теперь подбираем что можем двигать - 1 карту или стопку в Pile
        const movingCards =
            fromStack.type === KlondikeStackType.PILE ? this.klondikeRules.getPileMovableCards(card) : [card];
        if (movingCards.length === 0) {
            return false;
        }

        await Promise.all([this.moveCards(movingCards, fromStack, targetStack), this.flipCard(fromStack.topCard)]);

        return true;
    }

    private findAutoMoveTarget(card: IKlondikeCard): IKlondikeStack | null {
        const sourceStack = card.stack as IKlondikeStack;
        const sourceType = sourceStack.type;
        const isTopCard = sourceStack.topCard === card;

        if (sourceType !== KlondikeStackType.BASE && isTopCard) {
            for (const base of this.cardStacksMap.bases) {
                if (base === sourceStack) continue;
                if (this.klondikeRules.canMoveToBase(card, base)) {
                    return base;
                }
            }
        }

        for (const pile of this.cardStacksMap.piles) {
            if (pile === sourceStack) continue;
            if (this.klondikeRules.canMoveToPile(card, pile)) {
                return pile;
            }
        }

        return null;
    }

    private restoreDraggedCards(state: DragState) {
        state.cards.forEach((card) => {
            const start = state.startPositions.get(card);
            if (start) {
                card.x = start.x;
                card.y = start.y;
            }
        });
        state.fromStack.layout();
    }

    private async onPointerUp(pointer: Phaser.Input.Pointer, objects: (Phaser.GameObjects.GameObject | undefined)[]) {
        const gameObject = objects[0];
        const card = ifKlondikeCard(gameObject);
        if (card == null) return false;
        const fromStack = card.stack;

        console.log(`on click 
        value ${card.value} 
        suit ${card.suit} 
        stack ${fromStack.type} ${fromStack.id}  
      `);

        /** щелчок по колоде - извлекает карту в сброс **/
        if (fromStack.type === KlondikeStackType.DECK) {
            const topCard = this.cardStacksMap.deck.pickTopCard();
            if (topCard) {
                const movingCards = [topCard];
                const targetStack = this.cardStacksMap.grave;
                // перемещаем карточку как массив
                await this.moveCards(movingCards, fromStack, targetStack, 200);
                // флипаем ее на кладбище
                await this.flipCard(targetStack.topCard);
            }
            return;
        }

        /** если был драг - выходим **/
        const wasDrag = pointer.getDistance() > 10;
        if (wasDrag) return;

        /** пытаемся автоматически переместить **/
        const success = await this.tryAutoMove(card);
        if (!success) {
            this.onAutoMoveFail(card);
        }
    }

    /** движение карт - может быть анимированным **/
    private async moveCards(
        movingCards: IKlondikeCard[],
        fromStack: IKlondikeStack,
        targetStack: IKlondikeStack,
        duration = 300,
    ) {
        const topCard = movingCards[movingCards.length - 1];

        this.events.emit("cardMove", {
            suit: topCard.suit,
            value: topCard.value,
            fromStack: { type: fromStack.type, id: fromStack.id },
            toStack: { type: targetStack.type, id: targetStack.id }
        });

        movingCards.forEach((movingCard) => {
            fromStack.removeCard(movingCard);
        });

        const moveParams = layoutForAnimation({
            cards: movingCards,
            layout: () => {
                targetStack.placeCards(movingCards);
            },
        });

        if (this.state.isCardMoveAnimation) {
            await animateCardMove({moveParams, duration});
        }

        this.onCardMoveFinish(movingCards[movingCards.length - 1], fromStack, targetStack);
    }

    /** анимиированный флип карты **/
    private async flipCard(card?: IKlondikeCard, to: CardSide = "face") {
        if (card == null) return;
        const isFaced = card.isFaceUp ? to === "face" : to === "back";
        if (isFaced) return;
        if (this.state.isCardMoveAnimation) {
            await animateCardFlip({card});
        } else {
            card.flip(to);
        }
    }

    private onAutoMoveFail(card: IKlondikeCard) {
        animateCardShake({ card }).catch(console.warn);
        this.events.emit('cardAutoMoveFail', {
            suit: card.suit,
            value: card.value,
            fromStack: { type: card.stack.type, id: card.stack.id },
        })
    }
}
