import { Align } from "@kvisaz/phaser-sugar";
import { ASSETS, BackgroundAssetBuilder, getLocalizedText } from "../../assets";
import { uiIconSettingsButton, uiTextButton } from "../../ui";
import { Router, Scenes } from "../routes";

interface IProps {
  scene: Phaser.Scene;
}

export class StartView {
  constructor(private props: IProps) {
    const { scene } = this.props;
    const align = new Align();

    new BackgroundAssetBuilder(scene).sceneBg("start");

    const titleText = getLocalizedText("start.logo.title");
    const subTitleText = getLocalizedText("start.logo.subtitle");
    const buttonText = getLocalizedText("start.start");

    const title = scene.add.text(0, 0, titleText, {
      fontSize: 76,
      fontFamily: ASSETS.font.fonts.RuslanDisplay.fontFamily,
      color: "#87C91C",
      stroke: "#ffffff",
      strokeThickness: 8,
    });
    align.anchorSceneScreen(scene).centerX(title).topIn(title, 5);

    const subTitle = scene.add.text(0, 0, subTitleText, {
      fontSize: 70,
      fontFamily: ASSETS.font.fonts.RuslanDisplay.fontFamily,
      color: "#188500",
      stroke: "#ffffff",
      strokeThickness: 8,
      lineSpacing: 0,
    });
    align.anchorSceneScreen(scene).centerX(subTitle).bottomIn(subTitle, 10);

    /** start button **/
    const button = uiTextButton({
      scene,
      text: buttonText.toUpperCase(),
      type: "accent",
      onClick: () => new Router(scene).go(Scenes.Game),
    });
    scene.add.existing(button);
    align.anchorSceneScreen(scene).centerX(button).centerY(button, 240);

    /** settings button **/
    const uiSettingsButton = uiIconSettingsButton({ scene });
    scene.add.existing(uiSettingsButton);
    align.anchorSceneScreen(scene).rightIn(uiSettingsButton, -20).topIn(uiSettingsButton, 20);

    // testing
    // new Router(scene).go(Scenes.Game);
  }
}
