import { SceneEvents } from "../SceneEvents";
import { SoundMusicSettings } from "../services";
import { ASSETS } from "../assets";
import { globalEvents } from "../globalEvents";

interface IProps {
  scene: Phaser.Scene;
  soundMusicSettings: SoundMusicSettings;
}

/** Звуковой интерфейс юзера
 * Поставь его в начало каждой сцены **/
export class SoundManager {
  private unSubs?: (() => void)[];

  constructor(private props: IProps) {
    this.props.scene.events.once(
      Phaser.Scenes.Events.SHUTDOWN, // или .DESTROY, если нужен полный wipe
      this.destroy,
      this,
    );

    const sceneEvents = new SceneEvents(this.props.scene);
    this.props.soundMusicSettings.load();

    this.unSubs = [
      sceneEvents.on("soundSettingsOn", this.onSoundSettingsChange.bind(this)),
      sceneEvents.on("musicSettingsOn", this.onMusicSettingsChange.bind(this)),
      sceneEvents.on("musicPlay", this.onMusicPlay.bind(this)),
      globalEvents.on("playSound", (soundName) => ASSETS.sounds.effect[soundName](this.props.scene)),
    ];
  }

  /** выключить или поставить на паузу все звуки, временно **/
  onAdFullStart() {
    const { scene } = this.props;
    scene.sound.mute = true;
  }

  /** включить или снять с паузы все звуки, если они не были запрещены в настройках  **/
  onAdFullFinish() {
    const { soundMusicSettings, scene } = this.props;
    const isAllowed = soundMusicSettings.isSoundOn();
    scene.sound.mute = !(isAllowed && true);
  }

  destroy() {
    this.unSubs?.forEach((unSub) => unSub());
  }

  onSoundSettingsChange(isSoundOn: boolean) {
    const { soundMusicSettings, scene } = this.props;
    scene.sound.mute = !isSoundOn;
    soundMusicSettings.setSoundOn(isSoundOn);
    soundMusicSettings.save();
  }

  onMusicSettingsChange(isMusicOn: boolean) {
    const { soundMusicSettings } = this.props;
    soundMusicSettings.setMusicOn(isMusicOn);
    soundMusicSettings.save();

    /** включаем музыку при изменении настроек если она не играла **/
    this.playMusic(isMusicOn);
  }

  private playMusic(isPlay: boolean) {
    const { scene } = this.props;
    if (isPlay) {
      // ASSETS.sounds.music.playResumeLoad(scene);
    } else {
      // ASSETS.sounds.music.pause(scene);
    }
  }

  onMusicPlay() {
    const isAllowed = this.props.soundMusicSettings.isMusicOn();
    this.playMusic(isAllowed);
  }
}
