import { ASSETS } from "../../../assets";

export function addText(scene: Phaser.Scene, text: string, textStyle?: Phaser.Types.GameObjects.Text.TextStyle) {
  return new Phaser.GameObjects.Text(scene, 0, 0, text, {
    fontFamily: ASSETS.font.fonts.RobotoBold.fontFamily,
    fontSize: "32px",
    ...textStyle,
  });
}

export function addWarningText(scene: Phaser.Scene, text: string, textStyle?: Phaser.Types.GameObjects.Text.TextStyle) {
  return new Phaser.GameObjects.Text(scene, 0, 0, text, {
    fontFamily: ASSETS.font.fonts.RobotoBold.fontFamily,
    fontSize: "32px",
    color: "#f1ce3d",
    backgroundColor: "#930000",
    padding: {
      top: 10,
      right: 10,
      bottom: 10,
      left: 10,
    },
    ...textStyle,
  });
}
