import { Router, Scenes } from "../routes";
import { SoundManager } from "../../ui";
import { BackgroundAssetBuilder } from "../../assets";
import { Align } from "@kvisaz/phaser-sugar";
import { globalEvents } from "../../globalEvents";
import { services } from "../../serviceProvider";

export class AdFullScreenScene extends Phaser.Scene {
  constructor() {
    super(Scenes.AdFullScreen);
  }

  create() {
    const scene = this;
    const align = new Align();
    const { soundMusicSettings } = services;
    const soundManager = new SoundManager({ scene, soundMusicSettings });

    soundManager.onAdFullStart();

    new BackgroundAssetBuilder(scene).sceneBg();

    /** to do some neutral image **/

    /** уйти когда сервис рекламы передаст сообщение **/
    globalEvents.once("showAdsFullScreenFinish", () => {
      soundManager.onAdFullFinish();
      new Router(scene).restartFromFullAd();
    });
  }
}
