import { AlignObject } from "@kvisaz/phaser-sugar";
import { CardSide, IBoundable, ICardStack, IScalable } from "../../../common/games/cards-abstract/abstract_types";
import { CardSuit, CardValue } from "../../../common";

export enum KlondikeStackType {
  DECK = "deck",
  GRAVE = "grave",
  BASE = "base",
  PILE = "pile",
}

export interface IKlondikeStack extends ICardStack<IKlondikeCard> {
  type: KlondikeStackType;
}

export interface IKlondikeCard extends Phaser.GameObjects.GameObject, AlignObject, IBoundable, IScalable {
  flip(to: CardSide): void;

  type: string;
  value: CardValue;
  suit: CardSuit;
  isFaceUp: boolean;
  stack: IKlondikeStack;
}
