import { YandexGamesService } from "../YandexGamesService";
import { globalEvents } from "../../globalEvents";

/** закрытый от связи дубль-интерфейс для изоляции сервисов **/
interface IAdSettings {
  /** минимальный интервал между рекламами **/
  minimumIntervalSeconds: number;
  /** пропустить первые N сессий вообще без рекламы **/
  firstSessionsWithoutAds: number;
  /** пропустить первые N сессий В ДЕНЬ вообще без рекламы **/
  firstDaySessionsWithoutAds: number;
}

interface IProps {
  gameId: string;
  adSettings: IAdSettings;
  yandexGamesService: YandexGamesService;
}

interface IAdServiceState {
  lastAdsShowTime: number;
}

export class AdsService {
  public isEnabled = true;

  private state: IAdServiceState = {
    lastAdsShowTime: 0,
  };

  private get LS_KEY() {
    return `${this.props.gameId}-ads`;
  }

  constructor(private props: IProps) {
    // При Boot - YSDK сам показывает рекламу
    // поэтому давай отметим время, чтобы не частить
    globalEvents.once("bootSceneStart", () => {
      this.markEventAdTime();
    });

    globalEvents.on("showAdsFullScreenTry", () => {
      this.tryShowFullScreenAd((wasShown) => {
        globalEvents.emit('showAdsFullScreenFinish');
      });
    })
  }

  enable() {
    this.isEnabled = true;
  }

  disable() {
    this.isEnabled = false;
  }

  isAdAllowed(): boolean {
    if (!this.isEnabled) return false;
    const minimumMs = this.props.adSettings.firstSessionsWithoutAds * 1000;
    return this.isTimeAllowed(minimumMs);
  }

  tryShowFullScreenAd(onResult: (wasShown: boolean) => void) {
    try {
      if (!this.isAdAllowed()) {
        onResult(false);
        return;
      }
      // console.log("show FullScreenAd");
      this.props.yandexGamesService.showFullscreenAdv((wasShown) => {
        // если показана реклама - отмечаем время, чтобы не показывать еще раз быстро
        if (wasShown) {
          this.markEventAdTime();
        }
        onResult(wasShown);
      });
    } catch (e) {
      console.warn(e);
      onResult(false);
    }
  }

  private isTimeAllowed(minimumMs: number): boolean {
    return Date.now() - this.state.lastAdsShowTime >= minimumMs;
  }

  private markEventAdTime() {
    this.state.lastAdsShowTime = Date.now();
    this.saveState();
  }

  private saveState() {
    localStorage.setItem(this.LS_KEY, JSON.stringify(this.state));
  }

  private loadState() {
    let state = this.state;
    try {
      const stored = localStorage.getItem(this.LS_KEY);
      if (stored) {
        state = JSON.parse(stored);
      }
    } finally {
      this.state = state;
    }
  }
}
