import { gameConfig } from "./config";
import { ServiceProvider } from "./services";
import { MetaGameStats } from "./metagame";

/**
 * Отдельный сервиспровайдер для настройки на конкретную игру
 * лежит в отдельном файле
 * чтобы не было лишних и цикличных зависимостей
 * **/
export const services = new ServiceProvider({
  gameId: gameConfig.gameId,
  adSettings: gameConfig.addSettings,
});

/** Метагейм - сервис для работы с статистикой игры **/
export const metaGame = new MetaGameStats({
  database: services.gameDataService,
});
